import random, time, hashlib
from cryptography.hazmat.primitives import hashes
size=50*1024*1024
plaintext=random.randbytes(size)
iterations=5
import statistics

# measure cryptography
ct=[]
for _ in range(iterations):
    start=time.perf_counter();
    d=hashes.Hash(hashes.SHA256());
    d.update(plaintext);
    d.finalize();
    ct.append(time.perf_counter()-start)
print('cryptography',statistics.mean(ct))
ht=[]
for _ in range(iterations):
    start=time.perf_counter();
    hashlib.sha256(plaintext).digest();
    ht.append(time.perf_counter()-start)
print('hashlib',statistics.mean(ht))
